from core.migration_utils import default_tenant


def split_roles(apps, schema_editor):
    """Old roles: admin and ops become owner and team member of the default portal (ops with every
    area and edit rights, as before). Superusers become platform admins with no portal."""
    Profile = apps.get_model("core", "Profile")
    sections = ["customers", "numbers", "sms", "voice", "wholesale", "money"]
    for p in Profile.objects.select_related("user"):
        if p.user.is_superuser:
            p.tenant = None
        else:
            p.tenant = default_tenant(apps)
            if p.role == "admin":
                p.role = "owner"
            elif p.role != "client":
                p.role, p.sections, p.can_edit = "member", sections, True
        p.save()


